  ('make-one-chore-smaller', 'Make one chore smaller', 'Take the chore you dread, say why it exists, and find a version that takes 15 minutes instead of 90.', 'Diego M.', null, '[{"id":"t0","type":"text","x":0,"y":0,"text":"Make one chore smaller","size":32,"color":"#1e1e1e","w":900},{"id":"r1","type":"rect","x":0,"y":90,"w":336,"h":376,"strokeColor":"#1e1e1e","fill":"none","strokeWidth":2},{"id":"r2","type":"rect","x":436,"y":90,"w":336,"h":376,"strokeColor":"#1e1e1e","fill":"none","strokeWidth":2},{"id":"r3","type":"rect","x":872,"y":90,"w":336,"h":376,"strokeColor":"#1e1e1e","fill":"none","strokeWidth":2},{"id":"r4","type":"rect","x":0,"y":566,"w":772,"h":250,"strokeColor":"#1e1e1e","fill":"none","strokeWidth":2},{"id":"z1","type":"text","x":24,"y":106,"text":"The chore","size":24,"color":"#1e1e1e","w":300},{"id":"z2","type":"text","x":460,"y":106,"text":"Why it exists","size":24,"color":"#1e1e1e","w":300},{"id":"z3","type":"text","x":896,"y":106,"text":"Smaller version","size":24,"color":"#1e1e1e","w":300},{"id":"z4","type":"text","x":24,"y":582,"text":"Ask the AI on this board","size":24,"color":"#1e1e1e","w":724},{"id":"n1","type":"note","x":24,"y":154,"w":132,"h":132,"text":"Weekly meal planning, 90 min","fill":"#bfd7ff"},{"id":"n2","type":"note","x":180,"y":154,"w":132,"h":132,"text":"Happens: every Sunday night","fill":"#bfd7ff"},{"id":"n3","type":"note","x":24,"y":310,"w":132,"h":132,"text":"I dread it. I do it alone.","fill":"#bfd7ff"},{"id":"n4","type":"note","x":180,"y":310,"w":132,"h":132,"text":"Last time I ordered pizza","fill":"#bfd7ff"},{"id":"n5","type":"note","x":460,"y":154,"w":132,"h":132,"text":"Cheaper than eating out","fill":"#bfd7ff"},{"id":"n6","type":"note","x":616,"y":154,"w":132,"h":132,"text":"Kids need real dinners","fill":"#bfd7ff"},{"id":"n7","type":"note","x":460,"y":310,"w":132,"h":132,"text":"I feel guilty if I skip it","fill":"#bfd7ff"},{"id":"n8","type":"note","x":616,"y":310,"w":132,"h":132,"text":"Do I need a new plan every w