  ('first-time-with-ai', 'Your first time with AI', 'Say what you want in plain words, reply when it is not right, and try four easy first asks.', 'Nomvula K.', null, '[{"id":"t0","type":"text","x":0,"y":0,"text":"Your first time with AI","size":32,"color":"#1e1e1e","w":900},{"id":"r1","type":"rect","x":0,"y":90,"w":336,"h":376,"strokeColor":"#1e1e1e","fill":"none","strokeWidth":2},{"id":"r2","type":"rect","x":436,"y":90,"w":336,"h":376,"strokeColor":"#1e1e1e","fill":"none","strokeWidth":2},{"id":"r3","type":"rect","x":872,"y":90,"w":336,"h":376,"strokeColor":"#1e1e1e","fill":"none","strokeWidth":2},{"id":"r4","type":"rect","x":0,"y":566,"w":772,"h":250,"strokeColor":"#1e1e1e","fill":"none","strokeWidth":2},{"id":"z1","type":"text","x":24,"y":106,"text":"1. Say what you want","size":24,"color":"#1e1e1e","w":300},{"id":"z2","type":"text","x":460,"y":106,"text":"2. Read and reply","size":24,"color":"#1e1e1e","w":300},{"id":"z3","type":"text","x":896,"y":106,"text":"Easy first tries","size":24,"color":"#1e1e1e","w":300},{"id":"z4","type":"text","x":24,"y":582,"text":"Type this to the AI on this board","size":24,"color":"#1e1e1e","w":724},{"id":"n1","type":"note","x":24,"y":154,"w":132,"h":132,"text":"Type like you talk to a friend","fill":"#bfd7ff"},{"id":"n2","type":"note","x":180,"y":154,"w":132,"h":132,"text":"Say who you are in one line","fill":"#bfd7ff"},{"id":"n3","type":"note","x":24,"y":310,"w":132,"h":132,"text":"Say what you want back","fill":"#bfd7ff"},{"id":"n4","type":"note","x":180,"y":310,"w":132,"h":132,"text":"Short is fine. No tricks.","fill":"#bfd7ff"},{"id":"n5","type":"note","x":460,"y":154,"w":132,"h":132,"text":"Not right? Say what to change","fill":"#bfd7ff"},{"id":"n6","type":"note","x":616,"y":154,"w":132,"h":132,"text":"Say: shorter, simpler, cheaper","fill":"#bfd7ff"},{"id":"n7","type":"note","x":460,"y":310,"w":132,"h":132,"text":"Say: why did you suggest that?","fill":"#bfd7ff"},{"id":"n8","type":"note","x":616,"y":310,"w":132,"h":132,"tex