  ('say-the-hard-thing', 'Say the hard thing kindly', 'Lay out what happened and what you want, then get a calm message you can read out loud before you send it.', 'Ruth E.', 'ruth_writes_', '[{"id":"t0","type":"text","x":0,"y":0,"text":"Say the hard thing kindly","size":32,"color":"#1e1e1e","w":900},{"id":"r1","type":"rect","x":0,"y":90,"w":336,"h":376,"strokeColor":"#1e1e1e","fill":"none","strokeWidth":2},{"id":"r2","type":"rect","x":436,"y":90,"w":336,"h":376,"strokeColor":"#1e1e1e","fill":"none","strokeWidth":2},{"id":"r3","type":"rect","x":872,"y":90,"w":336,"h":376,"strokeColor":"#1e1e1e","fill":"none","strokeWidth":2},{"id":"r4","type":"rect","x":0,"y":566,"w":772,"h":250,"strokeColor":"#1e1e1e","fill":"none","strokeWidth":2},{"id":"z1","type":"text","x":24,"y":106,"text":"What happened","size":24,"color":"#1e1e1e","w":300},{"id":"z2","type":"text","x":460,"y":106,"text":"What I want","size":24,"color":"#1e1e1e","w":300},{"id":"z3","type":"text","x":896,"y":106,"text":"Then I say it","size":24,"color":"#1e1e1e","w":300},{"id":"z4","type":"text","x":24,"y":582,"text":"Type this to the AI on this board","size":24,"color":"#1e1e1e","w":724},{"id":"n1","type":"note","x":24,"y":154,"w":132,"h":132,"text":"My sister cancelled Mom’s birthday","fill":"#bfd7ff"},{"id":"n2","type":"note","x":180,"y":154,"w":132,"h":132,"text":"Third time this year","fill":"#bfd7ff"},{"id":"n3","type":"note","x":24,"y":310,"w":132,"h":132,"text":"I felt let down and said nothing","fill":"#bfd7ff"},{"id":"n4","type":"note","x":180,"y":310,"w":132,"h":132,"text":"It is still sitting in me","fill":"#bfd7ff"},{"id":"n5","type":"note","x":460,"y":154,"w":132,"h":132,"text":"She knows how it landed","fill":"#bfd7ff"},{"id":"n6","type":"note","x":616,"y":154,"w":132,"h":132,"text":"A plan for the next one","fill":"#bfd7ff"},{"id":"n7","type":"note","x":460,"y":310,"w":132,"h":132,"text":"Keep the relationship warm","fill":"#bfd7ff"},{"id":"n8","type":"note","x":616,"y":310,"w":132,"h":132,"tex